package hotel.documents;

import static org.junit.jupiter.api.Assertions.assertTrue;

import hotel.EmptyDatabase;
import hotel.reservations.Guest;
import hotel.reservations.NewReservation;
import hotel.reservations.Price;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import hotel.rooms.Room;
import hotel.rooms.Rooms;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class DocumentTypesTest {

    private final EmptyDatabase database = new EmptyDatabase();
    private final Rooms rooms = new Rooms(database.dataSource());
    private final ReservationStore store = new ReservationStore(database.dataSource());

    @AfterEach
    void closeDatabase() {
        database.close();
    }

    @Test
    void generatesCpfReceipt() {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        NewReservation request = new NewReservation(
                201, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 1, RatePlan.STANDARD);
        Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        Reservation reservation = store.add(request, price);
        Room room = rooms.find(201).orElseThrow();

        ReservationReceipt receipt = new ReservationReceipt(reservation, room);

        assertTrue(receipt.text().contains("Comprovante de reserva nº " + reservation.id()));
        assertTrue(receipt.text().contains("Ana Souza (CPF 123.456.789-09)"));
        assertTrue(receipt.text().contains("Quarto: 201 (DELUXE)"));
        assertTrue(receipt.text().contains("2 diárias"));
    }

    @Test
    void generatesCompanyReceipt() {
        Guest guest = new Guest("Ana Souza", "ana@example.com", null,
                "12.345.678/0001-90", "Tecnosul Ltda", null, null);
        NewReservation request = new NewReservation(
                201, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 1, RatePlan.STANDARD);
        Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        Reservation reservation = store.add(request, price);
        Room room = rooms.find(201).orElseThrow();

        ReservationReceipt receipt = new ReservationReceipt(reservation, room);

        assertTrue(receipt.text().contains("Fatura de hospedagem nº " + reservation.id()));
        assertTrue(receipt.text().contains("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"));
        assertTrue(receipt.text().contains("Hóspede: Ana Souza"));
        assertTrue(receipt.text().contains("ISS retido (5%)"));
    }

    @Test
    void generatesPassportReceipt() {
        Guest guest = new Guest("John Smith", "john@example.com", null,
                null, null, "X1234567", "United Kingdom");
        NewReservation request = new NewReservation(
                201, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 1, RatePlan.STANDARD);
        Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        Reservation reservation = store.add(request, price);
        Room room = rooms.find(201).orElseThrow();

        ReservationReceipt receipt = new ReservationReceipt(reservation, room);

        assertTrue(receipt.text().contains("Booking receipt no. " + reservation.id()));
        assertTrue(receipt.text().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
        assertTrue(receipt.text().contains("Check-in: 2027-03-10"));
        assertTrue(receipt.text().contains("2 nights"));
        assertTrue(receipt.text().contains("BRL "));
    }
}

